```verilog
`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire shift_ena;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .shift_ena(shift_ena)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // 3. Stimulus & self-checking
    integer errors = 0;
    integer cycle;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;

        // Apply reset for a couple of cycles
        @(posedge clk);
        #1;

        // Check reset behavior: shift_ena should be asserted for 4 cycles total.
        // Cycle 1 (active reset)
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error at cycle 1 (reset active): expected shift_ena = 1, got %b", shift_ena);
        end

        // Release reset
        @(posedge clk);
        reset = 0;
        #1;

        // Cycle 2
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error at cycle 2: expected shift_ena = 1, got %b", shift_ena);
        end

        // Cycle 3
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error at cycle 3: expected shift_ena = 1, got %b", shift_ena);
        end

        // Cycle 4 (last active cycle)
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error at cycle 4: expected shift_ena = 1, got %b", shift_ena);
        end

        // Cycle 5 (should be deasserted now and stay 0)
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b0) begin
            errors = errors + 1;
            $display("Error at cycle 5: expected shift_ena = 0, got %b", shift_ena);
        end

        // Check a few more cycles to ensure it stays 0 forever until reset
        repeat (5) begin
            @(posedge clk);
            #1;
            if (shift_ena !== 1'b0) begin
                errors = errors + 1;
                $display("Error during steady state: expected shift_ena = 0, got %b", shift_ena);
            end
        end

        // Test asynchronous/synchronous reset again mid-way
        reset = 1;
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error on re-reset cycle 1: expected shift_ena = 1, got %b", shift_ena);
        end

        reset = 0;
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error on re-reset cycle 2: expected shift_ena = 1, got %b", shift_ena);
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
```

